// Mouse precision index — record JAH-GPC-MOUSE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"dpi": 30000, "polling_hz": 8000};
var value = (m.dpi/1000*m.polling_hz/1000);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-MOUSE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-MOUSE-000001|' + value.toFixed(2) + ' precision index');

